//! 自包含趋势块：点证明按块内引用去重，展开保持旧 JSON 全字段与独立所有权。
use super::{StoreResult,StoreError,canonical,sha256,require};
use serde::{Serialize,Deserialize};
use crate::indexed_json::{Value,json};
use std::{collections::{BTreeMap,VecDeque},sync::{Arc,atomic::{AtomicU64,Ordering}}};
pub const POINT_FORMAT:&str="trend_point_refs_v2";
pub const MAX_EXPANDED_BYTES:usize=64*1024*1024;
static NEXT_OWNER:AtomicU64=AtomicU64::new(1);
#[derive(Clone,Debug,Serialize,Deserialize,PartialEq,Eq)]
pub struct EvidenceCertificate{pub owner:u64,pub node:u64,pub sha256:String}
struct EvidenceNode{certificate:EvidenceCertificate,value:Value,encoded:Arc<Vec<u8>>}
#[derive(Clone)]
pub struct CertifiedEvidence{inner:Arc<EvidenceNode>}
impl CertifiedEvidence{pub fn certificate(&self)->&EvidenceCertificate{&self.inner.certificate}pub fn value(&self)->&Value{&self.inner.value}}
pub struct EvidenceOwner{id:u64,next:u64}
impl Default for EvidenceOwner{fn default()->Self{Self{id:NEXT_OWNER.fetch_add(1,Ordering::Relaxed),next:0}}}
impl EvidenceOwner{pub fn certify(&mut self,value:Value)->StoreResult<CertifiedEvidence>{let bytes=canonical(&value)?.into_bytes();require(bytes.len()<=MAX_EXPANDED_BYTES,"evidence node exceeds expansion limit")?;let node=self.next;self.next=self.next.checked_add(1).ok_or_else(||StoreError("evidence reference overflow".into()))?;Ok(CertifiedEvidence{inner:Arc::new(EvidenceNode{certificate:EvidenceCertificate{owner:self.id,node,sha256:sha256(&bytes)},value,encoded:Arc::new(bytes)})})}}
/// 请求拥有的节点不可变，稳定证书不依赖裸指针或可重用的内存地址。
pub struct EvidenceJsonCache{pub max_bytes:usize,pub reused_bytes:usize,used:usize,entries:BTreeMap<String,Arc<Vec<u8>>>,lru:VecDeque<String>,owned:BTreeMap<(u64,u64),Arc<Vec<u8>>>}
impl EvidenceJsonCache{
    pub fn new(max_bytes:usize)->StoreResult<Self>{require(max_bytes>=1024,"evidence cache requires at least 1024 bytes")?;Ok(Self{max_bytes,reused_bytes:0,used:0,entries:BTreeMap::new(),lru:VecDeque::new(),owned:BTreeMap::new()})}
    pub fn memory_bytes(&self)->usize{self.used}
    pub fn clear(&mut self){self.entries.clear();self.lru.clear();self.owned.clear();self.used=0;}
    pub fn encode_certified(&mut self,node:&CertifiedEvidence)->Arc<Vec<u8>>{let key=(node.inner.certificate.owner,node.inner.certificate.node);if let Some(bytes)=self.owned.get(&key){self.reused_bytes+=bytes.len();return bytes.clone();}let bytes=node.inner.encoded.clone();let charge=bytes.len()+128;if self.used.saturating_add(charge)+1024<=self.max_bytes{self.used+=charge;self.owned.insert(key,bytes.clone());}bytes}
    pub fn encode(&mut self,value:&Value)->StoreResult<Arc<Vec<u8>>>{let bytes=canonical(value)?.into_bytes();require(bytes.len()<=MAX_EXPANDED_BYTES,"evidence JSON exceeds bound")?;let key=sha256(&bytes);if let Some(previous)=self.entries.get(&key){require(previous.as_slice()==bytes.as_slice(),"evidence hash collision")?;self.reused_bytes+=previous.len();let result=previous.clone();self.lru.retain(|old|old!=&key);self.lru.push_back(key);return Ok(result);}let charged=bytes.len()+192;let result=Arc::new(bytes);if charged+1024>self.max_bytes{return Ok(result);}while self.used.saturating_add(charged)+1024>self.max_bytes{let Some(old)=self.lru.pop_front()else{return Ok(result);};if let Some(bytes)=self.entries.remove(&old){self.used=self.used.saturating_sub(bytes.len()+192);}}self.entries.insert(key.clone(),result.clone());self.lru.push_back(key);self.used+=charged;Ok(result)}
}
#[derive(Default)]
pub struct TrendChunk{values:Vec<Value>,indices:BTreeMap<String,usize>,pub expanded_bytes:usize,pub encoded_bytes:usize}
impl TrendChunk{
    pub fn full(&self)->bool{self.expanded_bytes>=4*1024*1024||self.values.len()>=4096}
    fn intern(&mut self,value:&Value,cache:&mut EvidenceJsonCache)->StoreResult<usize>{let bytes=cache.encode(value)?;let key=sha256(bytes.as_slice());if let Some(index)=self.indices.get(&key){require(self.values[*index]==*value,"trend proof hash collision")?;return Ok(*index);}let index=self.values.len();self.encoded_bytes=self.encoded_bytes.saturating_add(bytes.len());self.values.push(value.clone());self.indices.insert(key,index);Ok(index)}
    fn stroke(&mut self,value:&Value,cache:&mut EvidenceJsonCache,depth:usize)->StoreResult<Value>{require(depth<=64,"trend leg nesting exceeds limit")?;let Some(object)=value.as_object()else{return Ok(json!({"value":value}));};let Some(points)=object.get("points").and_then(Value::as_array)else{return Ok(json!({"value":value}));};let mut metadata=object.clone();metadata.remove("points");let mut nested=BTreeMap::new();for name in ["structural_legs","confirmed_legs"]{if let Some(legs)=object.get(name).and_then(Value::as_array){metadata.remove(name);let legs=legs.iter().map(|leg|self.stroke(leg,cache,depth+1)).collect::<StoreResult<Vec<_>>>()?;nested.insert(name,legs);}}
        let references=points.iter().map(|point|self.intern(point,cache)).collect::<StoreResult<Vec<_>>>()?;let mut output=json!({"row":metadata,"points":references});for(name,legs)in nested{output[name]=json!(legs);}Ok(output)
    }
    pub fn encode(&mut self,row:&Value,cache:&mut EvidenceJsonCache)->StoreResult<(Value,usize)>{let expanded=canonical(row)?.len();require(expanded<=MAX_EXPANDED_BYTES,"single calculation row exceeds bound")?;self.expanded_bytes=self.expanded_bytes.saturating_add(expanded);let before=self.encoded_bytes;
        let encoded=if let Some(strokes)=row.get("strokes").and_then(Value::as_array){let mut metadata=row.as_object().ok_or_else(||StoreError("calculation row must be object".into()))?.clone();metadata.remove("strokes");let strokes=strokes.iter().map(|stroke|self.stroke(stroke,cache,0)).collect::<StoreResult<Vec<_>>>()?;json!({"row":metadata,"strokes":strokes})}else{json!({"value":row})};let size=canonical(&encoded)?.len()+self.encoded_bytes-before;self.encoded_bytes+=size.saturating_sub(self.encoded_bytes-before);Ok((encoded,size))
    }
    pub fn finish(self,rows:Vec<Value>)->Value{json!({"format":POINT_FORMAT,"values":self.values,"rows":rows})}
}
fn charge(size:usize,budget:&mut usize)->StoreResult<()>{require(size<=*budget,"calculation chunk expansion exceeds bound")?;*budget-=size;Ok(())}
fn reference(value:&Value,values:&[Value],sizes:&[usize],budget:&mut usize)->StoreResult<Value>{let index=value.as_u64().and_then(|v|usize::try_from(v).ok()).filter(|v|*v<values.len()).ok_or_else(||StoreError("invalid calculation point reference".into()))?;charge(sizes[index],budget)?;Ok(values[index].clone())}
fn restore_stroke(entry:&Value,values:&[Value],sizes:&[usize],budget:&mut usize,depth:usize)->StoreResult<Value>{require(depth<=64,"calculation leg nesting exceeds bound")?;let map=entry.as_object().ok_or_else(||StoreError("invalid calculation point stroke".into()))?;if map.len()==1&&map.contains_key("value"){let value=&map["value"];charge(canonical(value)?.len(),budget)?;return Ok(value.clone());}require(map.keys().all(|k|matches!(k.as_str(),"row"|"points"|"structural_legs"|"confirmed_legs")),"invalid calculation stroke keys")?;let metadata=map.get("row").and_then(Value::as_object).ok_or_else(||StoreError("calculation stroke metadata missing".into()))?;require(!metadata.contains_key("points"),"duplicated calculation points")?;charge(canonical(&json!(metadata))?.len(),budget)?;let mut row=metadata.clone();let points=map.get("points").and_then(Value::as_array).ok_or_else(||StoreError("calculation points missing".into()))?;row.insert("points".into(),json!(points.iter().map(|p|reference(p,values,sizes,budget)).collect::<StoreResult<Vec<_>>>()?));for name in ["structural_legs","confirmed_legs"]{if let Some(legs)=map.get(name){require(!row.contains_key(name),"duplicate calculation legs")?;let legs=legs.as_array().ok_or_else(||StoreError("invalid calculation leg table".into()))?;row.insert(name.into(),json!(legs.iter().map(|leg|restore_stroke(leg,values,sizes,budget,depth+1)).collect::<StoreResult<Vec<_>>>()?));}}Ok(Value::Object(row))}
pub fn restore_calculation_chunk(value:&Value)->StoreResult<Vec<Value>>{
    if let Some(rows)=value.as_array(){require(canonical(value)?.len()<=MAX_EXPANDED_BYTES,"legacy calculation chunk too large")?;return Ok(rows.clone());}
    let kind=value["format"].as_str().filter(|v|matches!(*v,"trend_stroke_refs_v1"|POINT_FORMAT)).ok_or_else(||StoreError("unsupported calculation chunk format".into()))?;let values=value["values"].as_array().ok_or_else(||StoreError("calculation value table missing".into()))?;let rows=value["rows"].as_array().ok_or_else(||StoreError("calculation rows missing".into()))?;let sizes=values.iter().map(|v|canonical(v).map(|v|v.len())).collect::<StoreResult<Vec<_>>>()?;let mut budget=MAX_EXPANDED_BYTES;let mut result=Vec::new();
    for entry in rows{let map=entry.as_object().ok_or_else(||StoreError("invalid calculation chunk row".into()))?;if map.len()==1&&map.get("value").is_some_and(Value::is_object){charge(canonical(&map["value"])?.len(),&mut budget)?;result.push(map["value"].clone());continue;}require(map.len()==2&&map.contains_key("row")&&map.contains_key("strokes"),"invalid calculation stroke row")?;let metadata=map["row"].as_object().ok_or_else(||StoreError("invalid calculation row metadata".into()))?;require(!metadata.contains_key("strokes"),"duplicate calculation strokes")?;charge(canonical(&json!(metadata))?.len(),&mut budget)?;let strokes=map["strokes"].as_array().ok_or_else(||StoreError("invalid calculation stroke table".into()))?;let mut row=metadata.clone();let restored=strokes.iter().map(|stroke|if kind==POINT_FORMAT{restore_stroke(stroke,values,&sizes,&mut budget,0)}else{reference(stroke,values,&sizes,&mut budget)}).collect::<StoreResult<Vec<_>>>()?;row.insert("strokes".into(),json!(restored));result.push(Value::Object(row));}Ok(result)
}
